/**
 * WITHHELD FROM THE SHELF — a wrong edition, not a broken file.
 *
 * `npm run audit:text` scored these three far above everything else in
 * the Archive:
 *
 *     king-lear     39.0% of lines are critical apparatus
 *     hamlet        32.3%
 *     the-tempest   11.1%
 *     next highest   2.9   (and that one is clean)
 *
 * All three are the Cambridge Shakespeare of Clark and Wright, 1863-66
 * — and the catalog says so, in the edition statement, exactly as
 * recorded. Nothing was mislabelled. That edition simply prints a full
 * apparatus beneath every page, and the scan folded it into the play:
 *
 *     140. at] Ff. om. Qq.
 *     63. smote] smot Q2Q3FIF2F3.
 *
 * A reader who opens Hamlet gets pages of sigla and a dramatis personae
 * reading POLOXIUS before a line of verse. Hamlet and King Lear even
 * share a sourceSha256 — both were cut from one volume file.
 *
 * Withheld rather than deleted, and withheld rather than left up. The
 * Archive's own law is that a work which will not resolve is ABSENT,
 * never a broken frame; a text that is 39% apparatus does not resolve
 * as the work it claims to be. The payloads stay on disk so a
 * re-ingest can be compared against them.
 *
 * The list is by ID and carries its reason, so restoring one is
 * deleting a line — and so that nobody later wonders why Shakespeare is
 * missing from a library that holds Marlowe and Webster.
 */
const BUILT = [...CORE_WORKS, ...LEGACY_REINGESTED_WORKS, ...LITERATURE_WORKS];
const workId = work => work.meta?.id ?? work.id ?? '';

/**
 * THE SHELF IS THE CANON. Everything else is withheld with its reason, which
 * is the rule the three Shakespeares already obeyed — now applied to the whole
 * archive rather than to the works we happened to catch (ARCHIVE-CANON-SPEC).
 */
const WITHHELD = withheldWorks(BUILT.map(workId));

/** Every work the Archive is prepared to serve. */
export const WITHHELD_WORKS = WITHHELD;

const WORKS = BUILT.filter(work => !Object.hasOwn(WITHHELD, workId(work)));

/**
 * A long work is not one reading, and its own sections are not its
 * divisions.
 *
 * The generated `sections` are where the ingest's heading detector
 * fired, which is not the same thing as where the book divides: 27% of
 * their names are prose caught mid-sentence, and the true heading is
 * stripped out of the content entirely. Handing those to a reader
 * offers War and Peace in 445 pieces, a third of them titled with
 * fragments of Tolstoy's sentences.
 *
 * So divisions.js reads the sections as EVIDENCE and reconstructs the
 * work's real scheme — merging the mis-cut fragments back into the
 * chapter they were taken from, and refusing to divide at all when no
 * scheme survives verification.
 */
function sequencesFor(meta, sections) {
    // `declared`, exactly as getDivisions asks it. Without it this asked the
    // divider to re-derive a scheme the edition had already stated, which is
    // the flatten-and-reconstruct the structured ingest exists to end — one
    // module reading the declaration and its neighbour guessing.
    const { entries } = divideSections(sections,
        { declared: STRUCTURED_IDS.has(meta.id) });
    return entries.map((entry, i) => ({
        id: `${meta.id}-${i + 1}`,
        name: entry.label,
        title: entry.title,
        content: entry.content,
        words: entry.words,
        // Ingested prose carries no authored phrase marks. Left at the
        // work's own pace rather than the system default, because these
        // are arguments to be followed, not aphorisms to be dwelt on.
        wpm: 200,
        curve: 'flat',
        description: entry.title
            ? `${entry.label} — ${entry.title}`
            : `${entry.label} of ${meta.title}`
    }));
}

/** Library-registry records for every ingested work. */
/**
 * The registry, built once.
 *
 * Each record closes over its own `cached` payload and `divisions`, so
 * a work is imported and divided the first time it is opened and not
 * again. That was true per RECORD and false per CALL: this function
 * rebuilt every closure on every invocation, so the caches were always
 * empty and each caller re-imported and re-divided whole books.
 *
 * Invisible in the Library, which asks once. Fatal for a Journey, which
 * asks while showing its introduction and again when a reader presses
 * Begin — the second pass re-read Milton, Homer and Jünger from
 * nothing, and Begin sat on "Preparing…".
 */
let registry = null;

export function ingestedArchiveTexts() {
    if (registry) return registry;
    registry = WORKS.map(({ meta, load }) => {
        let cached = null;
        let divisions = null;
        return {
            id: meta.id,
            title: meta.title,
            author: meta.author,
            category: meta.shelf,
            // An edition names itself one of two ways, and they must not
            // be concatenated. Interpolating both fields blindly gave
            // "Homer · undefined, 1883" where a publisher was absent,
            // and then "…Ernest Myers, 1883, 1883" once the hole was
            // patched, because a `statement` already carries its year.
            tradition: meta.edition.publisher
                ? `${meta.edition.publisher}, ${meta.edition.year}`
                : (meta.edition.statement || String(meta.edition.year || '')),
            description: meta.edition.translator
                ? `${meta.title}, translated by ${meta.edition.translator}.`
                : `${meta.title}.`,
            // What the work holds, and what IT calls them. Every card
            // used to read "0 verses" — a count that was wrong in a
            // noun that was wrong — because the payload had not loaded
            // and nothing else knew.
            chapterCount: DIVISION_INDEX[meta.id]?.count ?? null,
            chapterNoun: DIVISION_INDEX[meta.id]?.noun ?? null,
            chapterTitled: DIVISION_INDEX[meta.id]?.titled === true,
            wordCount: DIVISION_INDEX[meta.id]?.words ?? null,
            // A long work is entered at a division, not at its first
            // word. The Library reads this to decide whether to offer
            // a table of contents; it stays null until the payload
            // arrives, because the divisions are derived from it.
            divisions: null,
            getDivisions: async () => {
                if (!divisions) {
                    divisions = divideSections(await load(),
                        { declared: STRUCTURED_IDS.has(meta.id) });
                }
                return divisions;
            },
            /**
             * WHAT WE HOLD, as opposed to what we show.
             *
             * `getDivisions` is a display selection: it drops a
             * contents page, folds mis-cut fragments, and refuses a
             * scheme it cannot verify. Every one of those is the right
             * call for a reader and the wrong basis for an integrity
             * check — the question "are these the right bytes?" is
             * about the payload, and it must not be answerable
             * differently because the shelf changed how it presents
             * them.
             *
             * The identity invariant read the divisions and began
             * failing for four works the moment the index stopped being
             * offered as chapter one, which was a true statement about
             * the display and a false one about the holding.
             */
            getSections: async () => load(),
            defaultCurve: 'flat',
            defaultWpm: 200,
            tags: ['archive', 'ingested', meta.shelf],
            provider: 'archive-ingest',
            // The text arrives when asked for, once.
            getSequences: async () => {
                if (!cached) cached = sequencesFor(meta, await load());
                return cached;
            },
            provenance: {
                translator: meta.edition.translator,
                year: meta.edition.year,
                basis: meta.basis
            }
        };
    });
    return registry;
}

/** The declared metadata, for tests that check it against the payloads. */
export const INGESTED_META = WORKS.map(w => w.meta);
